WITH filtered AS (SELECT *, TRIM(dept_name) AS clean_dept_name FROM departments WHERE dept_name IS NOT NULL), with_windows AS (SELECT id, dept_name, location, budget, clean_dept_name, LAG(budget, 1) OVER (PARTITION BY location, dept_name ORDER BY budget, id) AS prev_budget, SUM(budget) OVER (PARTITION BY dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_budget FROM filtered), scored AS (SELECT *, MAX(running_budget) OVER (PARTITION BY dept_name, location) AS dept_name_max_running_budget, NTILE(10) OVER (PARTITION BY location, dept_name ORDER BY running_budget, id) AS running_budget_bucket FROM with_windows), cleaned AS (SELECT id, location, budget, clean_dept_name, prev_budget, running_budget, dept_name_max_running_budget, running_budget_bucket, TRIM(location) AS clean_location, FLOOR(prev_budget) AS prev_budget_whole, COALESCE(dept_name, 'NONE') AS resolved_dept_name FROM scored WHERE dept_name_max_running_budget >= 8712701), filtered_departments AS (SELECT *, COALESCE(budget, 0) AS budget_filled, COALESCE(location, 'NONE') AS location_filled FROM cleaned WHERE location IS NOT NULL) SELECT id, location, clean_dept_name, prev_budget, dept_name_max_running_budget, clean_location, prev_budget_whole, resolved_dept_name, budget_filled FROM filtered_departments;
